'use strict';
window.FinancePlanning=(()=>{
 let ctx,plans=[],limits=[],incomes=[],snapshots=[],reports=[],requests=[],ready=false,wired=false,editingIncome=null,editingAsset=null,lastFormKey='';
 const $=id=>document.getElementById(id),F=()=>window.FamilyAnalytics,eu=c=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(c/100),pct=v=>v===null?'—':new Intl.NumberFormat('pt-PT',{maximumFractionDigits:1}).format(v)+'%',now=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Lisbon'}).format(new Date());
 const labels={fixed:'Fixas',variable:'Variáveis',unclassified:'Por classificar',etf:'ETF',fund:'Fundos',ppr:'PPR',deposit:'Depósitos',stock:'Ações',bond:'Obrigações',cash:'Numerário',other:'Outros'};
 const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const scope=()=>ctx.accountId!=='all'?'account:'+ctx.accountId:ctx.bank,month=()=>ctx.month==='all'?now().slice(0,7):ctx.month,monthStart=()=>month()+'-01';
 const applicable=r=>r.household_id===ctx.home&&r.scope_key===scope()&&r.month===monthStart();
 const model=()=>F().compute({...ctx,asOf:now(),month:month(),plan:plans.find(applicable)||null,lines:limits.filter(applicable),incomes});
 function message(id,text,error=false){$(id).textContent=text;$(id).className='message '+(error?'error':'success');}
 async function fetchAll(table){let rows=[];for(let i=0;i<10000;i+=500){const r=await ctx.db.from(table).select('*').eq('household_id',ctx.home).order('id').range(i,i+499);if(r.error)throw r.error;rows.push(...r.data);if(r.data.length<500)return rows;}throw Error('O volume de planeamento excede o limite de leitura. Não são apresentados totais parciais.');}
 async function load(){[plans,limits,incomes,snapshots,reports,requests]=await Promise.all(['finance_monthly_plans','finance_budget_lines','finance_income_streams','finance_investment_snapshots','finance_ai_reports','finance_analysis_requests'].map(fetchAll));ready=true;}
 function bars(id,data){const target=$(id);target.replaceChildren();const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]);if(!entries.length){target.append(node('p','Sem dados para este período.','muted'));return;}const max=Math.max(1,...entries.map(x=>Math.abs(x[1])));for(const [label,v] of entries.slice(0,12)){const row=node('div',undefined,'bar-row'),t=node('div',undefined,'bar-title');t.append(node('span',label),node('strong',eu(v)));const track=node('div',undefined,'bar-track'),fill=node('div',undefined,'bar-fill');fill.style.width=(Math.abs(v)/max*100)+'%';if(v<0)fill.style.background='#8b698c';track.append(fill);row.append(t,track);target.append(row);}}
 function line(id,series,xLabel='Dias do mês',tickLabels={}){const target=$(id);target.replaceChildren();const valid=series.filter(s=>s.points.length);if(!valid.length){target.append(node('p','Ainda não existem avaliações ou movimentos suficientes para este gráfico.','muted'));return;}
  const NS='http://www.w3.org/2000/svg',svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 620 240');svg.setAttribute('role','img');svg.setAttribute('aria-label',valid.map(s=>s.name).join(' e '));const vals=valid.flatMap(s=>s.points.map(p=>p.y)),min=Math.min(0,...vals),max=Math.max(1,...vals),span=max-min;const xmin=Math.min(...valid.flatMap(s=>s.points.map(p=>p.x))),xmax=Math.max(xmin+1,...valid.flatMap(s=>s.points.map(p=>p.x))),X=x=>64+(x-xmin)/(xmax-xmin)*530,Y=y=>190-(y-min)/span*150;
  for(let i=0;i<=3;i++){const v=min+span*i/3,l=document.createElementNS(NS,'line');for(const [k,val] of Object.entries({x1:64,x2:595,y1:Y(v),y2:Y(v),stroke:'#e2e8df'}))l.setAttribute(k,val);svg.append(l);const t=document.createElementNS(NS,'text');t.setAttribute('x','1');t.setAttribute('y',Y(v)+4);t.textContent=eu(v);svg.append(t);}
  for(const s of valid){const path=document.createElementNS(NS,'polyline');path.setAttribute('points',s.points.map(p=>X(p.x)+','+Y(p.y)).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke',s.color);path.setAttribute('stroke-width','3');if(s.dashed)path.setAttribute('stroke-dasharray','7 5');svg.append(path);for(const p of [s.points[0],s.points.at(-1)]){const dot=document.createElementNS(NS,'circle');for(const [k,val] of Object.entries({cx:X(p.x),cy:Y(p.y),r:3,fill:s.color}))dot.setAttribute(k,val);const title=document.createElementNS(NS,'title');title.textContent=(p.label||p.x)+': '+eu(p.y);dot.append(title);svg.append(dot);}}
  for(const x of [...new Set([xmin,Math.round((xmin+xmax)/2),xmax])]){const t=document.createElementNS(NS,'text');t.setAttribute('x',X(x));t.setAttribute('y','213');t.textContent=tickLabels[x]??x;svg.append(t);}target.append(svg);const legend=node('div',undefined,'chart-legend');for(const s of valid){const n=node('span',s.name+' · '+eu(s.points.at(-1).y));n.style.borderColor=s.color;legend.append(n);}legend.append(node('small',xLabel));target.append(legend);
 }
 function cumulative(rs,start,end){let total=0;const sums={};for(const r of rs.filter(r=>['expense','refund'].includes(r.flow_kind)&&r.booked_on>=start&&r.booked_on<=end))sums[r.booked_on]=(sums[r.booked_on]||0)-F().cents(r.amount);const points=[{x:0,y:0}];for(let d=start;d<=end;d=F().shift(d,1)){total+=sums[d]||0;points.push({x:Number(d.slice(-2)),y:total,label:d});}return points;}
 function renderAnalysis(m){
  $('analysis-period').textContent=ctx.scopeLabel+' · '+month()+(ctx.month==='all'?' · a análise usa o mês atual; selecione um mês para mudar.':'')+(m.cutoff?' · último movimento observado: '+m.cutoff:'');
  const warnings=[];if(!m.cutoff)warnings.push('Sem movimentos neste mês; os valores não representam um mês com despesa zero.');if(!m.currentCoverage.ok)warnings.push('A cobertura não comprova todo o período: '+(m.currentCoverage.missing.join(', ')||'faltam extratos')+'.');if(m.cutoff&&m.cutoff<now()&&!m.full)warnings.push('Os dados terminam em '+m.cutoff+'. Atualize-os antes de decidir quanto pode gastar esta semana.');if(m.classificationIssues)warnings.push(m.classificationIssues+' movimentos de despesa têm categorias de investimento ou transferência. Confirmem a finalidade antes de interpretar os totais e a variação.');if(m.unresolved)warnings.push(m.unresolved+' movimentos precisam de revisão.');if(!m.full)warnings.push('Mês parcial. Projeções e limites semanais são indicativos.');$('analysis-warnings').textContent=warnings.join(' ')||'Período coberto pelos extratos disponíveis. As categorias continuam sujeitas à vossa revisão.';
  $('analysis-spend').textContent=m.cutoff?eu(m.net):'Sem dados';$('analysis-change').textContent=m.comparable?(m.difference>0?'+':'')+eu(m.difference)+' ('+pct(m.pct)+') face ao período anterior equivalente':'Comparação suspensa: falta cobertura comparável.';
  $('analysis-budget').textContent=m.budget===null?'Por definir':m.budget===0?(m.net>0?'Acima do limite zero':'Limite zero'):pct(m.pacePct);$('analysis-remaining').textContent=m.remaining===null?'Definam o limite em Orçamento.':eu(m.remaining)+(m.remaining<0?' acima do orçamento em valor absoluto.':' de margem no limite.');
  $('analysis-weekly').textContent=m.weeklyAllowance===null?'—':eu(m.weeklyAllowance);$('analysis-margin').textContent=m.plannedMargin===null?'Por definir':eu(m.plannedMargin);
  const scoped=ctx.rows.filter(r=>r.booked_on<=now()&&AccountReports.matches(r,ctx.accounts,ctx.bank,ctx.accountId));const series=m.cutoff?[{name:'Mês selecionado',color:'#173D35',points:cumulative(scoped,m.start,m.full?m.end:m.cutoff)}]:[];if(m.comparable)series.push({name:'Período anterior equivalente',color:'#887654',dashed:true,points:cumulative(scoped,F().prev(month())+'-01',m.compareEnd)});line('analysis-line',series);
  bars('analysis-macro',Object.fromEntries(Object.entries(m.macro).map(([k,v])=>[labels[k],v])));bars('analysis-top',$('analysis-granularity').value==='detail'?m.detailed:m.groups);
  const reduction=Math.min(50,Math.max(1,Number($('analysis-reduction').value)||10));$('analysis-opportunities').replaceChildren();const opportunities=Object.entries(m.adjustable).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,3);for(const [k,v] of opportunities){const p=node('p');p.append(node('strong',k),node('span',' · '+eu(v)+' registados. Uma redução ilustrativa de '+reduction+'% corresponderia a '+eu(v*reduction/100)+' sobre esta referência, sem garantia de poupança futura.'));$('analysis-opportunities').append(p);}if(!opportunities.length)$('analysis-opportunities').append(node('p','Ainda não há despesas variáveis ajustáveis claramente classificadas para sugerir reduções. Revejam as categorias.','muted'));
  const top=Object.entries(m.detailed).sort((a,b)=>b[1]-a[1])[0];let text=m.cutoff?'Até '+m.cutoff+', registam-se '+eu(m.net)+' de despesa líquida em '+ctx.scopeLabel+'. ':'Não há dados suficientes para resumir este mês. ';if(top)text+='A maior rubrica é '+top[0]+', com '+eu(top[1])+'. ';if(m.comparable)text+='Face ao período equivalente anterior, a despesa '+(m.difference>0?'aumentou ':m.difference<0?'diminuiu ':'manteve-se em ')+eu(Math.abs(m.difference))+'. ';if(m.budget===null)text+='Definam um orçamento para transformar esta leitura em controlo de limites. ';else if(m.remaining<0)text+='O limite mensal já foi ultrapassado em '+eu(-m.remaining)+'. Revejam despesas ajustáveis e pagamentos ainda pendentes. ';else text+='Restam '+eu(m.remaining)+' no limite mensal; este valor ainda pode ter de cobrir despesas fixas por pagar. ';if(m.week.comparable)text+='Nos últimos sete dias cobertos, a despesa foi '+eu(m.week.spending)+', contra '+eu(m.week.previous)+' nos sete anteriores. ';if(m.unresolved||m.classificationIssues)text+='As conclusões são provisórias enquanto houver movimentos por rever.';$('automatic-newsletter').textContent=text;
  $('budget-alert-list').replaceChildren();for(const l of m.budgetLines.filter(l=>l.remaining<0))$('budget-alert-list').append(node('p',l.category+': limite excedido em '+eu(-l.remaining)+'.','budget-over'));
  renderAI(m);
 }
 function planningKey(){return [plans.find(applicable)?.version||0,...limits.filter(applicable).map(r=>r.id+':'+r.version).sort(),...incomes.map(r=>r.id+':'+r.version).sort()].join('|');}
 function renderAI(m){const r=reports.filter(r=>r.scope_key===scope()&&r.period_start===m.start).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];$('ai-report-body').replaceChildren();if(!r){$('ai-report-meta').textContent='Ainda não foi guardada uma análise IA para este mês e este âmbito.';$('ai-report-stale').hidden=true;return;}$('ai-report-meta').textContent=r.title+' · revisão de '+new Date(r.created_at).toLocaleString('pt-PT',{timeZone:'Europe/Lisbon'})+' · dados até '+r.data_cutoff;for(const paragraph of r.body.split('\n').filter(Boolean))$('ai-report-body').append(node('p',paragraph));const latest=ctx.rows.filter(r=>AccountReports.matches(r,ctx.accounts,ctx.bank,ctx.accountId)&&r.booked_on>=m.start&&r.booked_on<=m.end).map(r=>r.updated_at).filter(Boolean).sort().at(-1)||'';const stale=r.metrics.transaction_count!==m.count||r.metrics.spending_cents!==m.net||r.metrics.last_update!==latest||r.metrics.planning_version!==planningKey()||r.metrics.portfolio_version!==snapshots.map(s=>s.id+':'+s.version).sort().join('|');$('ai-report-stale').hidden=!stale;$('ai-report-stale').textContent='Os dados ou planos mudaram desde esta análise. Leia o resumo automático atualizado e peça uma nova revisão IA.';}
 function fillForms(){const key=scope()+'|'+month();if(lastFormKey===key)return;lastFormKey=key;const p=plans.find(applicable);$('budget-month').value=month();$('budget-limit').value=p?.spending_limit??'';$('budget-savings').value=p?.savings_target??0;$('budget-emergency').value=p?.emergency_balance??'';$('budget-notes').value=p?.notes||'';}
 function renderBudget(m){const p=plans.find(applicable);$('budget-progress').replaceChildren();if(p){const progress=node('progress');progress.max=Math.max(1,m.budget);progress.value=Math.min(Math.max(0,m.net),Math.max(1,m.budget));progress.setAttribute('aria-label','Utilização do orçamento');$('budget-progress').append(progress,node('p',eu(m.net)+' de '+eu(m.budget)+' · '+(m.remaining<0?'excesso de '+eu(-m.remaining):'margem de '+eu(m.remaining))));}else $('budget-progress').append(node('p','Ainda não foi definido um orçamento para este âmbito e mês.','muted'));
  $('budget-summary').replaceChildren(node('p','Rendimento mensal previsto: '+(m.expectedIncome?eu(m.expectedIncome):'por registar')),node('p','Meta de poupança: '+(m.savingsTarget===null?'por definir':eu(m.savingsTarget))),node('p','Capacidade planeada de poupança: '+pct(m.plannedSavingsRate)));if(m.plannedMargin!==null)$('budget-summary').append(node('p','Margem depois de despesas planeadas e meta: '+eu(m.plannedMargin)));const total=m.budgetLines.reduce((n,l)=>n+l.limit,0);if(m.budget!==null&&total>m.budget)$('budget-summary').append(node('p','A soma dos limites por categoria excede o limite global. Ajustem a distribuição.','budget-over'));
  $('budget-lines').replaceChildren();for(const line of limits.filter(applicable).filter(l=>l.active)){const actual=m.groups[line.category]||0,card=node('article',undefined,'record-row'),body=node('div');body.append(node('strong',line.category),node('p',eu(actual)+' realizados / '+eu(F().cents(line.amount_limit))+' planeados'));const actions=node('div'),edit=node('button','Alterar','text-button'),remove=node('button','Retirar limite','text-button');edit.type=remove.type='button';edit.onclick=()=>{$('budget-line-category').value=line.category;$('budget-line-limit').value=line.amount_limit;};remove.onclick=async()=>{try{await save('finance_budget_lines',{active:false},line);await refresh();}catch(e){message('budget-line-message',e.message,true);}};actions.append(edit,remove);card.append(body,actions);$('budget-lines').append(card);}}
 function renderIncome(m){$('income-planned').textContent=m.expectedIncome?eu(m.expectedIncome):'Por registar';$('income-observed').textContent=m.cutoff?eu(m.actualIncome):'Sem dados';$('income-stream-list').replaceChildren();const list=incomes.filter(i=>AccountReports.matches({account_id:i.account_id},ctx.accounts,ctx.bank,ctx.accountId)).sort((a,b)=>a.person.localeCompare(b.person)||b.start_month.localeCompare(a.start_month));for(const i of list){const row=node('article',undefined,'record-row'),body=node('div');body.append(node('strong',i.person+' · '+i.label),node('p',eu(F().cents(i.net_monthly))+' líquidos/mês · '+i.start_month.slice(0,7)+' até '+(i.end_month?.slice(0,7)||'sem fim definido')+' · '+(i.pay_day?'dia habitual '+i.pay_day+' · ':'')+(ctx.accounts.find(a=>a.id===i.account_id)?.label||'Conta')));const b=node('button','Alterar','secondary');b.onclick=()=>openIncome(i);row.append(body,b);$('income-stream-list').append(row);}if(!list.length)$('income-stream-list').append(node('p','Adicionem os salários e outros rendimentos regulares. Estes valores são planeamento e não alteram os extratos.','empty'));}
 function portfolioRows(){return snapshots.filter(s=>s.account_id?AccountReports.matches({account_id:s.account_id},ctx.accounts,ctx.bank,ctx.accountId):ctx.bank==='all'&&ctx.accountId==='all');}
 function renderPortfolio(){const asOf=F().last(month())<now()?F().last(month()):now(),list=portfolioRows(),latest=F().latestSnapshots(list,asOf);$('portfolio-value').textContent=latest.length?eu(latest.reduce((n,r)=>n+F().cents(r.market_value),0)):'Por registar';const complete=latest.length&&latest.every(r=>r.net_contributed!==null&&r.net_contributed!==undefined);$('portfolio-gain').textContent=complete?eu(latest.reduce((n,r)=>n+F().cents(r.market_value)-F().cents(r.net_contributed),0)):'Capital em falta';$('portfolio-date-note').textContent=latest.length?'Datas de referência: '+[...new Set(latest.map(r=>r.as_of))].sort().join(', ')+'. Valores de datas diferentes podem estar desatualizados.':'Registem uma avaliação para começar. Não são usados valores de ficheiros históricos sem revisão.';
  const insights=$('portfolio-insights');insights.replaceChildren();if(latest.length){const total=latest.reduce((n,r)=>n+F().cents(r.market_value),0),largest=[...latest].sort((a,b)=>Number(b.market_value)-Number(a.market_value))[0];insights.append(node('p','Há '+latest.length+' componentes avaliadas. '+largest.asset_label+' representa '+pct(total>0?F().cents(largest.market_value)/total*100:null)+' deste subtotal. São valores documentados, não cotações atuais.'));for(const current of latest){const history=list.filter(r=>r.asset_label===current.asset_label&&r.as_of<=current.as_of).sort((a,b)=>a.as_of.localeCompare(b.as_of)),previous=history.at(-2);if(previous)insights.append(node('p',current.asset_label+': variação de valor de '+eu(F().cents(current.market_value)-F().cents(previous.market_value))+' entre '+previous.as_of+' e '+current.as_of+'. Pode incluir aportes e levantamentos; não é uma medida de rendibilidade.'));}}else insights.append(node('p','Ainda não há avaliações neste âmbito. Escolhe Família para ver as instituições independentes dos bancos.'));const allocation={};for(const r of latest)allocation[labels[r.asset_class]]=(allocation[labels[r.asset_class]]||0)+F().cents(r.market_value);bars('portfolio-allocation',allocation);const old=$('portfolio-asset-filter').value;$('portfolio-asset-filter').replaceChildren();for(const label of [...new Set(list.filter(r=>r.as_of<=asOf).map(r=>r.asset_label))].sort()){const o=node('option',label);o.value=label;$('portfolio-asset-filter').append(o);}if([...$('portfolio-asset-filter').options].some(o=>o.value===old))$('portfolio-asset-filter').value=old;
  $('investment-snapshot-list').replaceChildren();for(const r of latest){const row=node('article',undefined,'record-row'),body=node('div');body.append(node('strong',r.asset_label+' · '+eu(F().cents(r.market_value))),node('p',r.institution+' · '+labels[r.asset_class]+' · referência '+r.as_of),node('p',r.notes||'Sem notas.'));const b=node('button','Corrigir / atualizar','secondary');b.onclick=()=>openAsset(r);const source=r.notes?.match(/https:\/\/drive\.google\.com\/file\/d\/[A-Za-z0-9_-]+\/view/);if(source){const a=node('a','Abrir documento de origem','text-link');a.href=source[0];a.target='_blank';a.rel='noopener';body.append(a);}row.append(body,b);$('investment-snapshot-list').append(row);}renderAssetHistory();}
 function renderAssetHistory(){const label=$('portfolio-asset-filter').value,list=portfolioRows().filter(r=>r.asset_label===label&&r.as_of<=(F().last(month())<now()?F().last(month()):now())).sort((a,b)=>a.as_of.localeCompare(b.as_of));line('portfolio-history',list.length?[{name:label,color:'#173D35',points:list.map((r,i)=>({x:i+1,y:F().cents(r.market_value),label:r.as_of}))}]:[],'Avaliações por ordem de data');}
 async function save(table,patch,old){let r;if(old)r=await ctx.db.from(table).update(patch).eq('household_id',ctx.home).eq('id',old.id).eq('version',old.version).select('*');else r=await ctx.db.from(table).insert({...patch,household_id:ctx.home}).select('*');if(r.error)throw r.error;if(!r.data?.length)throw Error('O registo mudou entretanto. Atualize os dados antes de voltar a guardar.');return r.data[0];}
 async function refresh(){await load();lastFormKey='';render();}
 function render(){if(!ctx||!ready)return;const m=model();renderAnalysis(m);fillForms();renderBudget(m);renderIncome(m);renderPortfolio();window.FinanceEvolution?.render({...ctx,snapshots});}
 function accountChoices(id,selected){$(id).replaceChildren();for(const a of ctx.accounts){const o=node('option',a.label);o.value=a.id;$(id).append(o);}if(selected)$(id).value=selected;else if(ctx.accountId!=='all')$(id).value=ctx.accountId;}
 function openIncome(i=null){editingIncome=i;$('income-person').value=i?.person||'';$('income-label').value=i?.label||'Salário';$('income-amount').value=i?.net_monthly??'';$('income-day').value=i?.pay_day??'';$('income-start').value=i?.start_month?.slice(0,7)||month();$('income-end').value=i?.end_month?.slice(0,7)||'';accountChoices('income-account',i?.account_id);message('income-message','');$('income-dialog').showModal();}
 function openAsset(r=null){editingAsset=r;$('asset-label').value=r?.asset_label||'';$('asset-institution').value=r?.institution||'';$('asset-class').value=r?.asset_class||'etf';$('asset-date').value=r?.as_of||now();$('asset-date').max=now();$('asset-value').value=r?.market_value??'';$('asset-capital').value=r?.net_contributed??'';$('asset-notes').value=r?.notes||'';accountChoices('asset-account',r?.account_id);message('investment-message',r?'Para registar uma nova avaliação, altere a data; a avaliação antiga será preservada.':'');$('investment-dialog').showModal();}
 async function action(button,messageId,fn){$(button).disabled=true;message(messageId,'');try{await fn();}catch(e){message(messageId,e.message,true);}finally{$(button).disabled=false;}}
 function wire(){if(wired)return;wired=true;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('analysis-granularity').onchange=$('analysis-reduction').oninput=()=>renderAnalysis(model());$('portfolio-asset-filter').onchange=renderAssetHistory;$('add-income').onclick=()=>openIncome();$('add-investment-snapshot').onclick=()=>openAsset();
  $('budget-form').onsubmit=e=>{e.preventDefault();action('save-budget','budget-message',async()=>{const mo=$('budget-month').value+'-01',patch={scope_key:scope(),month:mo,spending_limit:Number($('budget-limit').value),savings_target:Number($('budget-savings').value),emergency_balance:$('budget-emergency').value===''?null:Number($('budget-emergency').value),notes:$('budget-notes').value.trim()};const old=plans.find(p=>p.scope_key===scope()&&p.month===mo);await save('finance_monthly_plans',patch,old);await refresh();ctx.setMonth?.(mo.slice(0,7));message('budget-message','Orçamento guardado para '+mo.slice(0,7)+'.');});};
  $('budget-line-form').onsubmit=e=>{e.preventDefault();action('save-budget-line','budget-line-message',async()=>{const category=$('budget-line-category').value.trim(),old=limits.find(l=>applicable(l)&&l.category===category);await save('finance_budget_lines',{scope_key:scope(),month:monthStart(),category,amount_limit:Number($('budget-line-limit').value),active:true},old);await refresh();message('budget-line-message','Limite guardado.');});};
  $('income-form').onsubmit=e=>{e.preventDefault();action('save-income','income-message',async()=>{const patch={person:$('income-person').value.trim(),label:$('income-label').value.trim(),account_id:$('income-account').value,net_monthly:Number($('income-amount').value),pay_day:$('income-day').value?Number($('income-day').value):null,start_month:$('income-start').value+'-01',end_month:$('income-end').value?$('income-end').value+'-01':null};if(patch.end_month&&patch.end_month<patch.start_month)throw Error('O mês final tem de ser posterior ou igual ao inicial.');const overlap=incomes.some(i=>i.id!==editingIncome?.id&&i.person.toLocaleLowerCase()===patch.person.toLocaleLowerCase()&&i.label.toLocaleLowerCase()===patch.label.toLocaleLowerCase()&&i.account_id===patch.account_id&&i.start_month<=(patch.end_month||'9999-12-01')&&(!i.end_month||i.end_month>=patch.start_month));if(overlap)throw Error('Já existe um período sobreposto para esta fonte. Termine ou corrija o período anterior.');await save('finance_income_streams',patch,editingIncome);$('income-dialog').close();await refresh();});};
  $('investment-form').onsubmit=e=>{e.preventDefault();action('save-investment','investment-message',async()=>{const patch={asset_label:$('asset-label').value.trim(),institution:$('asset-institution').value.trim(),account_id:$('asset-account').value,asset_class:$('asset-class').value,as_of:$('asset-date').value,market_value:Number($('asset-value').value),net_contributed:$('asset-capital').value===''?null:Number($('asset-capital').value),notes:$('asset-notes').value.trim()};if(patch.as_of>now())throw Error('Use uma data de avaliação já observada.');const other=snapshots.find(r=>r.asset_label===patch.asset_label&&r.account_id!==patch.account_id);if(other)throw Error('Este nome já identifica uma aplicação noutra conta. Use um nome diferente para preservar o histórico.');const old=snapshots.find(r=>r.asset_label===patch.asset_label&&r.as_of===patch.as_of);await save('finance_investment_snapshots',patch,old||null);$('investment-dialog').close();await refresh();});};
  $('request-ai-analysis').onclick=()=>action('request-ai-analysis','ai-request-message',async()=>{if(requests.some(r=>r.scope_key===scope()&&r.month===monthStart()&&r.status==='pending')){message('ai-request-message','Já existe um pedido pendente para este período.');return;}const r=await ctx.db.from('finance_analysis_requests').insert({household_id:ctx.home,scope_key:scope(),month:monthStart()}).select('id');if(r.error)throw r.error;await load();message('ai-request-message','Pedido guardado. Peça ao assistente a revisão das análises pendentes na próxima atualização.');});
 }
 return {async sync(data){ctx=data;wire();try{await load();for(const id of ['save-budget','save-budget-line','add-income','add-investment-snapshot','request-ai-analysis'])$(id).disabled=false;document.querySelectorAll('.planning-pending').forEach(n=>n.hidden=true);render();}catch(e){plans=[];limits=[];incomes=[];snapshots=[];reports=[];requests=[];ready=true;render();document.querySelectorAll('.planning-pending').forEach(n=>n.hidden=false);for(const id of ['save-budget','save-budget-line','add-income','add-investment-snapshot','request-ai-analysis'])$(id).disabled=true;}},update(data){ctx={...ctx,...data};render();},reset(){ctx=null;ready=false;plans=[];limits=[];incomes=[];snapshots=[];reports=[];requests=[];lastFormKey='';},model,lineChart:line};
})();
